    private fun symbol(name: String, data: String, mirrored: Boolean): ImageVector =
        ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = mirrored).apply {
            group(translationY = 960f) {
                addPath(PathParser().parsePathString(data).toNodes(), fill = SolidColor(Color.Black))
            }
        }.build()
}

/** Decorative icons use null; the enclosing control supplies the accessible label. */
@Composable
fun AppIcon(image: ImageVector, modifier: Modifier = Modifier, contentDescription: String? = null) {
    Icon(imageVector = image, contentDescription = contentDescription, modifier = modifier)
}
